29: static int handle_ping(struct mg_connection *conn, void *cbdata) {
30:     const struct mg_request_info *ri = mg_get_request_info(conn);
31:     char query[1024];
32:     char host[256] = "127.0.0.1";
33:     
34:     if (ri->query_string) {
35:         strncpy(query, ri->query_string, sizeof(query) - 1);
36:         query[sizeof(query) - 1] = '\0';
37:         
38:         char *host_param = strstr(query, "host=");
39:         if (host_param) {
40:             char *value = host_param + 5;
41:             size_t i = 0;
42:             while (value[i] && value[i] != '&' && i < sizeof(host) - 1) {
43:                 host[i] = value[i];
44:                 i++;
45:             }
46:             host[i] = '\0';
47:             
48:             char *decoded = url_decode(host);
49:             if (decoded) {
50:                 strncpy(host, decoded, sizeof(host) - 1);
51:                 host[sizeof(host) - 1] = '\0';
52:                 free(decoded);
53:             }
54:         }
55:     }
56:     
57:     log_access("/ping", host);
58:     
59:     if (!validate_hostname(host)) {
60:         send_error_response(conn, 400, "Invalid hostname");
61:         return 400;
62:     }
63:     
64:     char command[512];
65:     snprintf(command, sizeof(command), "ping -c 4 %s", host);
66:     
67:     FILE *pipe = popen(command, "r");
68:     if (!pipe) {
69:         send_error_response(conn, 500, "Internal Server Error");
70:         return 500;
71:     }
72:     
73:     char buffer[1024];
74:     size_t nread;
75:     
76:     mg_send_http_ok(conn, "text/plain", 0);
77:     mg_printf(conn, "Executed command: %s\n\n", command);
78:     
79:     while ((nread = fread(buffer, 1, sizeof(buffer), pipe)) > 0) {
80:         mg_write(conn, buffer, nread);
81:     }
82:     
83:     pclose(pipe);
84:     return 200;
85: }

